public synchronized void send(final String message) {
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }

    // Ensure a telnet‑friendly line terminator (\r\n)
    String telnetMessage = message.endsWith("\r\n") ? message : message + "\r\n";

    // Assume there is a thread‑safe list of client output streams called `clientOutputs`
    if (clientOutputs == null || clientOutputs.isEmpty()) {
        return;
    }

    // Iterate over the list and send the message to each client
    // Any client that throws an exception will be removed from the list
    Iterator<PrintWriter> iterator = clientOutputs.iterator();
    while (iterator.hasNext()) {
        PrintWriter out = iterator.next();
        if (out == null) {
            iterator.remove(); // clean up null entries
            continue;
        }
        try {
            out.print(telnetMessage);
            out.flush();
            // If the writer reports an error, remove it from the list
            if (out.checkError()) {
                iterator.remove();
            }
        } catch (Exception e) {
            // Any exception indicates a broken client; remove it
            iterator.remove();
        }
    }
