protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long maxDuration = FETCH_DATA_DURATION;
    if (maxDuration <= 0) {
        return ranges;
    }
    long currentStart = start;
    while (currentStart < end) {
        long potentialEnd = currentStart + maxDuration;
        long currentEnd;
        if (potentialEnd < 0 || potentialEnd > end) {
            currentEnd = end;
        } else {
            currentEnd = potentialEnd;
        }
        try {
            ranges.add(new TimeRange(currentStart, currentEnd));
        } catch (Exception ex) {
            throw new RuntimeException("Error creating TimeRange", ex);
        }
        if (currentEnd == currentStart) {
            break; // prevent infinite loop in case of overflow
        }
        currentStart = currentEnd;
    }
    return ranges;
