static long compressTimeBucket(long timeBucket,int dayStep){
    try{
        if(timeBucket <= 0 || dayStep <= 0){
            return timeBucket;
        }
        int year = (int)(timeBucket / 10000);
        int month = (int)((timeBucket / 100) % 100);
        int day = (int)(timeBucket % 100);

        java.time.LocalDate date = java.time.LocalDate.of(year, month, day);
        int daysInMonth = date.lengthOfMonth();

        int bucketDay = ((day - 1) / dayStep) * dayStep + 1;
        if(bucketDay > daysInMonth){
            bucketDay = daysInMonth;
        }

        return year * 10000L + month * 100L + bucketDay;
    }catch(Exception e){
        return timeBucket;
    }
