public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string must not be null");
    }
    if (index < 0 || len < 0 || index > str.length() - len) {
        throw new IllegalArgumentException("Index and length out of bounds");
    }
    int utf8Size = 0;
    int i = index;
    int end = index + len;
    while (i < end) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            utf8Size += 1;
        } else if (ch <= 0x7FF) {
            utf8Size += 2;
        } else if (ch >= 0xD800 && ch <= 0xDBFF) { // high surrogate
            if (i + 1 < end) {
                char low = str.charAt(i + 1);
                if (low >= 0xDC00 && low <= 0xDFFF) { // valid surrogate pair
                    utf8Size += 4;
                    i++; // skip low surrogate
                } else {
                    // unpaired high surrogate: encode as 3 bytes
                    utf8Size += 3;
                }
            } else {
                // high surrogate at end: encode as 3 bytes
                utf8Size += 3;
            }
        } else {
            // non-ascii non-surrogate (<=0xFFFF)
            utf8Size += 3;
        }
        i++;
    }
    return utf8Size;
