private static String substituteValue(String text, Properties props, java.util.Set<String> visited) {
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
    java.util.regex.Matcher matcher = pattern.matcher(text);
    java.lang.StringBuffer sb = new java.lang.StringBuffer();
    while (matcher.find()) {
        String var = matcher.group(1).trim();
        // Support optional default value using colon
        String[] parts = var.split(":", 2);
        String propName = parts[0];
        String defaultVal = parts.length > 1 ? parts[1] : null;
        if (visited.contains(propName)) {
            // Circular reference detected; leave placeholder unchanged
            matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement("${" + propName + "}"));
            continue;
        }
        visited.add(propName);
        String replacement = props.getProperty(propName);
        if (replacement == null) {
            replacement = defaultVal != null ? defaultVal : "${" + propName + "}";
        } else {
            replacement = substituteValue(replacement, props, visited);
        }
        visited.remove(propName);
        matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(replacement));
    }
    matcher.appendTail(sb);
    return sb.toString();
