private int removeInactiveNodeRecursively(Category node) {
    int removedCount = 0;
    List<Category> children = node.getChildren();
    if (children == null) {
        return 0;
    }

    // Use an iterator to safely remove elements while iterating.
    java.util.Iterator<Category> iterator = children.iterator();
    while (iterator.hasNext()) {
        Category child = iterator.next();
        if (!child.isActive()) {
            // Entire subtree under this child should be removed.
            int subtreeSize = countAllNodes(child);
            iterator.remove();
            removedCount += subtreeSize;
        } else {
            // Recursively process active children.
            removedCount += removeInactiveNodeRecursively(child);
        }
    }

    return removedCount;
}

