public byte readByte() throws IOException {
    // If we have exhausted the current buffer, refill it from the underlying stream.
    if (pos >= limit) {
        // Attempt to read up to the size of the buffer.
        int readLength = in.read(buf, 0, buf.length);
        if (readLength == -1) {
            // End of stream; no more data available.
            throw new IOException("No more data available");
        }
        // Reset buffer pointers to the newly read data.
        pos = 0;
        limit = readLength;
    }
    // Return the next byte from the buffer.
    return buf[pos++];
