protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty() || graph == null) {
        return null;
    }

    // Use a list to record the vertices and edges in traversal order
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList   = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();

    // Pick an arbitrary start vertex from the first edge
    E firstEdge = tour.iterator().next();
    V currentVertex = graph.getEdgeSource(firstEdge);

    // Edge navigation loop
    while (visitedEdges.size() < tour.size()) {
        vertexList.add(currentVertex);

        // Find the next unvisited edge incident to the current vertex
        E nextEdge = null;
        for (E e : graph.edgesOf(currentVertex)) {
            if (!tour.contains(e)) {
                continue;
            }
            if (!visitedEdges.contains(e)) {
                nextEdge = e;
                break;
            }
        }

        if (nextEdge == null) {
            // No unvisited edge found – the set may not form a proper tour
            break;
        }

        edgeList.add(nextEdge);
        visitedEdges.add(nextEdge);

        // Determine the vertex on the other side of the edge
        V source = graph.getEdgeSource(nextEdge);
        V target = graph.getEdgeTarget(nextEdge);
        currentVertex = source.equals(currentVertex) ? target : source;
    }

    // Add the final vertex to close the path
    vertexList.add(currentVertex);

    // Compute total weight (if the graph supports it)
    double totalWeight = 0.0;
    for (E e : edgeList) {
        totalWeight += graph.getEdgeWeight(e);
    }

    return new GraphPathImpl<>(graph, vertexList.get(0), vertexList.get(vertexList.size() - 1), edgeList, totalWeight);
}<|return|>

