private String unescapeId(String input) {
    if (input == null) {
        throw new IllegalArgumentException("input cannot be null");
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                sb.append('\\');
                continue;
            }
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'a':
                    sb.append('\u0007'); // bell
                    i++;
                    break;
                case 'v':
                    sb.append('\u000B'); // vertical tab
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '?':
                    sb.append('?');
                    i++;
                    break;
                case 'x':
                    // hex escape \xHH (up to 2 hex digits)
                    int hexStart = i + 2;
                    if (hexStart < len && isHexDigit(input.charAt(hexStart))) {
                        int j = hexStart;
                        while (j < len && isHexDigit(input.charAt(j)) && j - hexStart < 2) {
                            j++;
                        }
                        String hex = input.substring(hexStart, j);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append((char) val);
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('x').append(hex);
                        }
                        i = j - 1;
                    } else {
                        sb.append('\\').append('x');
                        i++;
                    }
                    break;
                default:
                    if (isOctDigit(next)) {
                        int j = i + 1;
                        int count = 0;
                        while (j < len && isOctDigit(input.charAt(j)) && count < 3) {
                            j++;
                            count++;
                        }
                        String oct = input.substring(i + 1, j);
                        try {
                            int val = Integer.parseInt(oct, 8);
                            sb.append((char) val);
                        } catch (NumberFormatException e) {
                            sb.append('\\').append(next);
                        }
                        i = j - 1;
                    } else {
                        sb.append(next);
                        i++;
                    }
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

private boolean isHexDigit(char c) {
    return (c >= '0' && c <= '9')
            || (c >= 'a' && c <= 'f')
            || (c >= 'A' && c <= 'F');
}

private boolean isOctDigit(char c) {
    return c >= '0' && c <= '7';
