private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null) {
        return;
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        return;
    }

    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    if (minBucket == null || minBucket.isEmpty()) {
        return;
    }

    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    if (zeroBucket == null) {
        zeroBucket = new java.util.HashSet<Integer>();
        try {
            bucketsByLabel.set(0, zeroBucket);
        } catch (IndexOutOfBoundsException e) {
            // If the list isn't long enough, ignore as the bucket 0 cannot be updated.
            return;
        }
    }

    // Copy to avoid ConcurrentModificationException if minBucket is modified while iterating
    for (Integer v : new java.util.HashSet<Integer>(minBucket)) {
        if (v == null) {
            continue;
        }
        zeroBucket.add(v);
        if (v >= 0 && v < labels.size()) {
            labels.set(v, 0);
        }
    }

    minBucket.clear();
}<|return|>

